def check_D(D, Y, num_terms=50):
    y = [0.0]
    for n in range(2, num_terms + 1):
        intervals = []
        for m in range(1, n):
            lower = y[m-1] - D / (n + m)
            upper = y[m-1] + D / (n + m)
            intervals.append((lower, upper))

        intervals.sort()

        current_y = 0.0
        for lower, upper in intervals:
            if current_y < lower:
                break
            if current_y < upper:
                current_y = upper

        if current_y > Y:
            return False
        y.append(current_y)
    return True

Y = 100
for D in range(100, 401, 20):
    if check_D(D, Y, num_terms=100):
        print(f"D={D} is possible for Y={Y}")
